int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags)
{
    int bytes_received;
    struct sk_buff *skb;
    struct sockaddr *addr;

    if (sock->sk->sk_state != TCP_ESTABLISHED && sock->sk->sk_state != TCP_LISTEN) {
        return -EINVAL;
    }

    if (skb_queue_empty(&sock->sk->sk_receive_queue)) {
        if (flags & MSG_DONTWAIT) {
            return -EAGAIN;
        }
        schedule();
    }

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb) {
        return -EAGAIN;
    }

    bytes_received = skb->len;
    if (len < (size_t)skb->len) {
        bytes_received = len;
    }

    if (memcpy_to_msg(msg, skb->data, bytes_received) < 0) {
        skb_queue_head(&sock->sk->sk_receive_queue, skb);
        return -EFAULT;
    }

    if (sock->type == SOCK_DGRAM) {
        addr = (struct sockaddr *)&skb->cb;
        msg->msg_name = addr;
        msg->msg_namelen = sizeof(struct sockaddr);
    }

    if (sock->type == SOCK_STREAM) {
        kfree_skb(skb);
    } else {
        skb_queue_head(&sock->sk->sk_receive_queue, skb);
    }

    return bytes_received;
}

ssize_t sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    ssize_t res = -EAGAIN;

    if (sk->sk_state == TCP_CLOSE)
        return 0;

    if (sk->sk_data_qlen == 0) {
        if ((flags & MSG_DONTWAIT) || (sk->sk_shutdown & RCV_SHUTDOWN))
            return -EAGAIN;

        while (sk->sk_data_qlen == 0) {
            if (signal_pending(current))
                return -EINTR;
            schedule();
        }
    }

    struct sk_buff *skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (sock->type == SOCK_DGRAM) {
        msg->msg_name = (void *)&skb->pkt_type;
        msg->msg_namelen = sizeof(skb->pkt_type);
    }

    res = skb->len;
    if (res > len)
        res = len;

    memcpy(msg->msg_iov->iov_base, skb->data, res);
    msg->msg_iov->iov_base += res;
    msg->msg_iov->iov_len -= res;

    if (sock->type == SOCK_STREAM)
        kfree_skb(skb);
    else
        skb_queue_head(&sk->sk_receive_queue, skb);

    return res;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t len, int flags) {
    struct sock *sk = sock->sk;
    int error;
    int data_len;

    if (sk->sk_state == TCP_LISTEN)
        return -ENOTCONN;

    if (sk->sk_type == SOCK_DGRAM && sock->ops->recvmsg == NULL)
        return -EOPNOTSUPP;

    if (flags & MSG_OOB) {
        error = sk->prot->recvmsg(sk, msg, len, flags);
        if (error >= 0)
            data_len = error;
        return error;
    }

    if (sk->sk_type == SOCK_DGRAM) {
        if (sk->sk_data_len == 0)
            return -EAGAIN;

        data_len = sk->sk_data_len;
        if (data_len > len)
            data_len = len;

        error = memcpy_to_msg(msg, sk->sk_data, data_len);
        if (error)
            return error;

        sk->sk_data_len -= data_len;
        if (sk->sk_data_len == 0)
            sk->sk_data = NULL;

        return data_len;
    }

    if (sk->sk_type == SOCK_STREAM) {
        if (sk->sk_rcv_queue == NULL)
            return -EAGAIN;

        data_len = sk->sk_rcv_queue->len;
        if (data_len > len)
            data_len = len;

        error = memcpy_to_msg(msg, sk->sk_rcv_queue->data, data_len);
        if (error)
            return error;

        sk->sk_rcv_queue->len -= data_len;
        return data_len;
    }

    return -EINVAL;
}

int recv_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;

    if (sock->type == SOCK_DGRAM) {
        skb = skb_dequeue(&sock->sk->sk_receive_queue);
        if (!skb) {
            return -EAGAIN;
        }
    } else {
        skb = skb_recv_datagram(sock->sk, flags, &err);
        if (!skb) {
            return err;
        }
    }

    copied = skb->len;
    if (len < copied) {
        if (!(flags & MSG_TRUNC)) {
            copied = len;
        } else {
            msg->msg_flags |= MSG_TRUNC;
        }
    }

    if (sock->type == SOCK_DGRAM) {
        if (msg->msg_name) {
            struct sockaddr_in *addr = (struct sockaddr_in *)msg->msg_name;
            addr->sin_family = AF_INET;
            addr->sin_addr.s_addr = skb->sp->saddr;
            msg->msg_namelen = sizeof(*addr);
        }
    }

    if (skb_copy_datagram_msg(skb, 0, msg, 0, copied)) {
        kfree_skb(skb);
        return -EFAULT;
    }

    if (sock->type == SOCK_DGRAM) {
        kfree_skb(skb);
    } else {
        skb_consume_datagram(sock->sk, skb);
    }

    return copied;
}

ssize_t sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int err;

    if (sk->sk_state == TCP_LISTEN)
        return -ENOTCONN;

    if (sk->sk_data_qlen == 0)
        return -EAGAIN;

    if (flags & MSG_OOB) {
        skb = sk->sk_urg_data;
        if (!skb)
            return -EINVAL;

        copied = skb->len;
        err = skb_copy_datagram_const_msg(msg, 0, skb, 0, copied);
        if (err)
            return err;

        sk->sk_urg_data = NULL;
        return copied;
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    copied = skb->len;
    err = skb_copy_datagram_const_msg(msg, 0, skb, 0, copied);
    if (err)
        goto out_free_skb;

    if (sock->type == SOCK_DGRAM)
        memcpy(&msg->msg_name, &skb->cb, sizeof(struct sockaddr));

    if (skb->len > 0 && (flags & MSG_PEEK)) {
        skb_queue_head(&sk->sk_receive_queue, skb);
        copied = 0;
    } else {
        kfree_skb(skb);
    }

    return copied;

out_free_skb:
    kfree_skb(skb);
    return err;
}
